{
  "candidates": [
    {
      "explanation": "Coordinated pipeline-aware relaxation: node0 reduces order to avoid overloading upstream, node1 and node2 increase orders to replenish depleted inventories and clear backlogs, with node2 receiving extra to compensate for its large backlog.",
      "rules": [
        {
          "when": "agent==0 and backlog>0 and pipeline>20",
          "delta": "-2"
        },
        {
          "when": "agent==1 and inventory<2 and backlog==0",
          "delta": "2"
        },
        {
          "when": "agent==2 and backlog>10",
          "delta": "3"
        }
      ]
    },
    {
      "explanation": "Demand-responsive correction: all nodes increase orders when recent demand exceeds baseline, but node0 caps increase to prevent upstream overload, while downstream nodes order more aggressively to recover from stockouts.",
      "rules": [
        {
          "when": "growth>1.2 and agent==0",
          "delta": "min(2, (recent-baseline))"
        },
        {
          "when": "growth>1.2 and agent==1",
          "delta": "min(4, (recent-baseline))"
        },
        {
          "when": "growth>1.2 and agent==2",
          "delta": "min(5, (recent-baseline))"
        }
      ]
    },
    {
      "explanation": "Backlog-focused correction: nodes with backlog increase orders proportionally to backlog, but node0 limits increase to avoid worsening upstream backlog, while node2 increases most due to its critical backlog.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(2, backlog/5)"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(3, backlog/3)"
        },
        {
          "when": "agent==2 and backlog>0",
          "delta": "min(6, backlog/2)"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand to avoid overstock, but boost if backlog is high. Node0 has high backlog and pipeline, so slight reduction; node1 pipeline high, reduce; node2 pipeline moderate, keep.",
      "rules": [
        {
          "when": "agent==0 and backlog>20 and pipeline>60",
          "delta": "-2"
        },
        {
          "when": "agent==1 and pipeline>60 and backlog<5",
          "delta": "-3"
        },
        {
          "when": "agent==2 and pipeline>50 and backlog<5",
          "delta": "-1"
        }
      ]
    },
    {
      "explanation": "Growth-responsive coordination: increase orders when recent demand growth is high, but cap increases if pipeline already exceeds recent demand. Node0 backlog high, so increase; node1 and node2 increase moderately to prevent future stockouts.",
      "rules": [
        {
          "when": "agent==0 and backlog>20",
          "delta": "min(4, max(0, recent - pipeline/4))"
        },
        {
          "when": "agent==1 and backlog<5 and pipeline<recent*4",
          "delta": "2"
        },
        {
          "when": "agent==2 and backlog<5 and pipeline<recent*3",
          "delta": "1"
        }
      ]
    },
    {
      "explanation": "Backlog-focused: prioritize clearing backlog at node0 by increasing order, while keeping node1 and node2 orders steady to avoid creating upstream backlog. Node0 backlog high, so boost; node1 and node2 no change.",
      "rules": [
        {
          "when": "agent==0 and backlog>10",
          "delta": "min(6, backlog/10)"
        },
        {
          "when": "agent==1",
          "delta": "0"
        },
        {
          "when": "agent==2",
          "delta": "0"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Detects demand surge via growth>1.2 and raises orders at all nodes, with larger increases upstream to prevent pipeline starvation. Node0 and node1 get +4, node2 gets +6 to build buffer.",
      "rules": [
        {
          "when": "growth > 1.2",
          "delta": "if agent == 0 then 4 else if agent == 1 then 4 else 6"
        }
      ]
    },
    {
      "explanation": "When downstream backlog exists and upstream has inventory, increase upstream order to replenish pipeline. Node1 and node2 get +3 if their backlog>0, else 0.",
      "rules": [
        {
          "when": "backlog > 0 and agent > 0",
          "delta": "3"
        }
      ]
    },
    {
      "explanation": "If pipeline is low relative to recent demand, boost orders to avoid stockouts. Node0 and node1 get +2 if pipeline < recent*4, else 0.",
      "rules": [
        {
          "when": "pipeline < recent * 4 and agent < 2",
          "delta": "2"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Moderate pipeline-aware relaxation: reduce orders when backlog is high and pipeline is large, but allow small increases if recent demand growth is strong. Downstream nodes get larger reductions to avoid starving upstream.",
      "rules": [
        {
          "when": "backlog > 0 and pipeline > 40",
          "delta": "max(-6, min(0, -backlog/10 + (growth-1)*5))"
        },
        {
          "when": "backlog > 0 and pipeline <= 40",
          "delta": "max(-3, min(2, (growth-1)*10))"
        },
        {
          "when": "backlog == 0 and inventory > 0",
          "delta": "max(-2, min(2, (growth-1)*5))"
        }
      ]
    },
    {
      "explanation": "Aggressive backlog reduction: cut orders sharply when backlog exists, especially if pipeline is already high. Small increases only when backlog is zero and demand is growing.",
      "rules": [
        {
          "when": "backlog > 0",
          "delta": "max(-6, -backlog/5)"
        },
        {
          "when": "backlog == 0 and growth > 1.1",
          "delta": "min(3, (growth-1)*10)"
        },
        {
          "when": "backlog == 0 and growth <= 1.1",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware smoothing: adjust orders based on pipeline coverage relative to recent demand. If pipeline is high, reduce; if low, increase modestly. Backlog triggers stronger cuts.",
      "rules": [
        {
          "when": "pipeline > recent * 3",
          "delta": "max(-6, -2 - backlog/10)"
        },
        {
          "when": "pipeline < recent * 2 and backlog == 0",
          "delta": "min(4, (recent - pipeline/2)/2)"
        },
        {
          "when": "backlog > 0",
          "delta": "max(-6, -backlog/8)"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Refines the best prior candidate (llm_r0_0) by strengthening node1 and node2 replenishment while keeping node0's upstream relief. Node0 reduces order when backlog and pipeline are high to avoid overloading upstream. Node1 increases order when backlog is high and pipeline is low to clear its large backlog. Node2 increases order when backlog is high and pipeline is low to clear its critical backlog. All deltas are small and coordinated.",
      "rules": [
        {
          "when": "agent==0 and backlog>0 and pipeline>20",
          "delta": "-2"
        },
        {
          "when": "agent==1 and backlog>50 and pipeline<100",
          "delta": "3"
        },
        {
          "when": "agent==2 and backlog>30 and pipeline<100",
          "delta": "4"
        }
      ]
    }
  ]
}

